public static METUserSecurityGroup find(METUserSecurityGroupId  _userSecurityGroupId,
                                        boolean                 _forUpdate = false)
{
    METUserSecurityGroup userSecurityGroup;
    ;
    if (_userSecurityGroupId)
    {
        userSecurityGroup.selectForUpdate(_forUpdate);

        select firstonly userSecurityGroup
            where userSecurityGroup.UserSecurityGroupId  == _userSecurityGroupId;
    }

    return userSecurityGroup;
}

public static METModuleCustVend findSingleRebateModuleByUser(UserId _userId = curUserId())
{
    METUserSecurityGroup             metUserSecurityGroup;
    METUserSecurityGroupList         metUserSecurityGroupList;
    boolean                          hasCust;
    boolean                          hasVend;

    while select TAMRebateModuleCustVend from metUserSecurityGroup
      group by TAMRebateModuleCustVend
      exists join metUserSecurityGroupList
          where metUserSecurityGroupList.UserSecurityGroupId == metUserSecurityGroup.UserSecurityGroupId
             && metUserSecurityGroupList.UserId == _userId
    {
        switch (metUserSecurityGroup.TAMRebateModuleCustVend)
        {
            case METModuleCustVend::Cust:
                hasCust = true;
                break;
            case METModuleCustVend::Vend:
                hasVend = true;
                break;
        }
    }

    if (hasCust && hasVend)
    {
        return METModuleCustVend::NotApplicable;
    }
    else if (hasCust)
    {
        return METModuleCustVend::Cust;
    }
    else if (hasVend)
    {
        return METModuleCustVend::Vend;
    }

    return METModuleCustVend::NotApplicable;
}
